mapper.select:
SELECT

FROM (
    SELECT q.id, q.company_id, q.job_type, q.skill_tags, q.question_type, q.difficulty,
           q.content, q.content_sha256, q.key_points, q.reference_answer, q.evaluation_points,
           q.source, q.status, q.version, q.created_by, q.created_at, q.updated_at,
           q.deleted_at, q.reviewed_by, q.reviewed_at, q.review_reason,
           ROW_NUMBER() OVER (PARTITION BY q.question_type ORDER BY


                       (

                           IF(JSON_CONTAINS(q.skill_tags, JSON_ARRAY(#{tag})), 1, 0)

                       ) DESC,


                       0.0 DESC,


               CASE WHEN #{q.difficulty} IS NOT NULL AND #{q.difficulty} != '' AND q.difficulty = #{q.difficulty}
                    THEN 0 ELSE 1 END ASC,
               q.id ASC
           ) AS rn
    FROM job_question q
    WHERE q.company_id = #{q.companyId}
      AND q.status = 'ACTIVE'
      AND q.deleted_at IS NULL

          AND q.job_type = #{q.jobType}


          AND q.question_type = #{q.questionType}


          AND q.difficulty = #{q.difficulty}

) t
WHERE t.rn = 1
LIMIT 4

SELECT
FROM ( SELECT q.id, q.company_id, q.job_type, q.skill_tags, q.question_type, q.difficulty, q.content, q.content_sha256, q.key_points, q.reference_answer, q.evaluation_points, q.source, q.status, q.version, q.created_by, q.created_at, q.updated_at, q.deleted_at, q.reviewed_by, q.reviewed_at, q.review_reason, ROW_NUMBER() OVER (PARTITION BY q.question_type ORDER BY
(
IF(JSON_CONTAINS(q.skill_tags, JSON_ARRAY(#{tag})), 1, 0)
) DESC,
0.0 DESC,
CASE WHEN #{q.difficulty} IS NOT NULL AND #{q.difficulty} != '' AND q.difficulty = #{q.difficulty} THEN 0 ELSE 1 END ASC, q.id ASC ) AS rn FROM job_question q WHERE q.company_id = #{q.companyId} AND q.status = 'ACTIVE' AND q.deleted_at IS NULL AND q.question_type IN ('BASIC','PROJECT','BOUNDARY','COMPREHENSIVE')
AND q.job_type = #{q.jobType}
AND q.question_type = #{q.questionType}
) t WHERE t.rn = 1 LIMIT 4

SELECT id, company_id, job_type, skill_tags, question_type, difficulty, content, content_sha256,
       source, status, version, created_by, created_at, updated_at, deleted_at,
       reviewed_by, reviewed_at, review_reason
FROM job_question
WHERE company_id = #{companyId} AND deleted_at IS NULL

    AND job_type = #{q.jobType}


    AND question_type = #{q.questionType}


    AND difficulty = #{q.difficulty}


    AND status = #{q.status}

ORDER BY id DESC
